## Target contract: `SimpleDAO`
A bare call head (no `<var>.` prefix) targets this contract. Its callable functions (exact signatures from the ABI):
- credit(address) -> uint256  [view]
- donate(address to)  [payable]
- queryCredit(address to) -> uint256
- withdraw(uint256 amount)

## Contract Source
```solidity
pragma solidity ^0.4.2;

contract SimpleDAO {
mapping (address => uint) public credit;

function donate(address to) payable {
credit[to] += msg.value;
}

function withdraw(uint amount) {
if (credit[msg.sender]>= amount) {

bool res = msg.sender.call.value(amount)();
credit[msg.sender]-=amount;
}
}

function queryCredit(address to) returns (uint){
return credit[to];
}
}
```

